import React, { useMemo, useState } from "react";
import { ChevronLeft, ChevronRight, Plus } from "lucide-react";
import { toast } from "sonner";
import { TopBar } from "../../shared/components";
import { COLORS } from "../../config/colors";
import { useCalendario } from "../../hooks";
import { supabase } from "../../lib/supabase";
import { eventTypeMeta, calendarEvents } from "./calendarioData";
import type { TipoEventoKey, EventoCalendario } from "./calendario.types";
import { NovoEventoModal, NovoEventoFormData } from "../../components/modals/NovoEventoModal";
import { AlertBanner } from "../../components/AlertBanner";
import {
  getWeekDays,
  getMonthDays,
  addDays,
  addMonths,
  isSameDay,
  formatDayLabel,
  formatWeekRangeLabel,
  formatMonthLabel,
  toISODate,
} from "./calendarioUtils";
import {
  calendarioStyles as styles,
  getDayLabelStyle,
  getLegendDotStyle,
  getEventCardStyle,
  getToggleButtonStyle,
} from "./calendario.styles";

type ViewMode = "semana" | "mes";

export const Calendario: React.FC = () => {
  const [modalOpen, setModalOpen] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>("semana");
  const [referenceDate, setReferenceDate] = useState(new Date());
  const [localEvents, setLocalEvents] = useState<EventoCalendario[]>(calendarEvents);
  const [draggedEvent, setDraggedEvent] = useState<EventoCalendario | null>(null);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragTargetDate, setDragTargetDate] = useState<Date | null>(null);
  const [doubleClickEvent, setDoubleClickEvent] = useState<EventoCalendario | null>(null);

  const { data: supabaseEvents, refetch } = useCalendario();

  // Transform db events to local format, or fallback to mock events
  const events = (supabaseEvents && supabaseEvents.length > 0) ? supabaseEvents : localEvents;

  // Hooks DEVEM vir antes de qualquer return early
  const days = useMemo(
    () => (viewMode === "semana" ? getWeekDays(referenceDate) : getMonthDays(referenceDate)),
    [viewMode, referenceDate]
  );

  const rangeLabel = viewMode === "semana" ? formatWeekRangeLabel(days) : formatMonthLabel(referenceDate);

  const handlePrev = () => {
    setReferenceDate((prev) => (viewMode === "semana" ? addDays(prev, -7) : addMonths(prev, -1)));
  };

  const handleNext = () => {
    setReferenceDate((prev) => (viewMode === "semana" ? addDays(prev, 7) : addMonths(prev, 1)));
  };

  // Handler para arrastar eventos
  const handleMouseDown = (mouseEvent: React.MouseEvent, evento: EventoCalendario) => {
    setDraggedEvent(evento);
    setIsDragging(true);
    setDragOffset({
      x: mouseEvent.clientX,
      y: mouseEvent.clientY,
    });
    setDragTargetDate(null);
    mouseEvent.preventDefault();
  };

  const handleMouseMove = (event: React.MouseEvent) => {
    if (!isDragging || !draggedEvent) return;

    const dx = event.clientX - dragOffset.x;
    const dy = event.clientY - dragOffset.y;

    // Only start dragging after a minimum distance
    if (Math.sqrt(dx * dx + dy * dy) < 5) return;

    // Find which day was targeted
    const targetDay = days.find(day => {
      const daySelector = `.day-${toISODate(day)}`;
      const dayElement = document.querySelector(daySelector);
      if (!dayElement) return false;
      const rect = dayElement.getBoundingClientRect();
      return event.clientY >= rect.top && event.clientY <= rect.bottom;
    });

    setDragTargetDate(targetDay ?? null);
  };

  const handleMouseUp = () => {
    if (!isDragging || !draggedEvent) return;

    const targetDate = dragTargetDate;
    if (!targetDate) {
      setIsDragging(false);
      setDraggedEvent(null);
      return;
    }

    // Move the event to the target day
    const targetIso = toISODate(targetDate);
    const eventToMove = events.find(e => e.data === draggedEvent.data && e.titulo === draggedEvent.titulo);

    if (eventToMove) {
      // Remove from original day
      const updatedEvents = events.filter(e => !(e.data === draggedEvent.data && e.titulo === draggedEvent.titulo));
      // Add to target day (avoid duplicates)
      const alreadyExists = updatedEvents.some(e => e.data === targetIso && e.titulo === draggedEvent.titulo);
      if (!alreadyExists) {
        updatedEvents.push({
          ...eventToMove,
          data: targetIso,
        });
      }
      setLocalEvents(updatedEvents as EventoCalendario[]);
      toast.success(`Evento movido para ${formatDayLabel(targetDate)}`);
    }

    setIsDragging(false);
    setDraggedEvent(null);
    setDragTargetDate(null);
  };

  // Handler para duplo clique - abrir modal de edi??o
  const handleDoubleClick = (evento: EventoCalendario) => {
    setDoubleClickEvent(evento);
    setModalOpen(true);
  };

  const handleModalClose = () => {
    setDoubleClickEvent(null);
    setModalOpen(false);
  };

  const handleSaveEvento = async (data: NovoEventoFormData) => {
    const novo: EventoCalendario = {
      data: data.data,
      hora: data.hora,
      titulo: data.titulo,
      tipo: data.tipo,
    };
    try {
      const inicio = `${data.data}T${data.hora}:00`;
      const fim = `${data.data}T${data.hora}:00`;
      const payload = {
        titulo: data.titulo,
        tipo: data.tipo,
        data_hora_inicio: inicio,
        data_hora_fim: fim,
        descricao: "",
      };
      await supabase.from("calendario_eventos").insert(payload);
      toast.success("Evento adicionado ao calendário");
      setModalOpen(false);
      refetch();
    } catch {
      // Fallback local em modo apresentação
      setLocalEvents(prev => [...prev, novo]);
      toast.success("Evento adicionado ao calendário");
      setModalOpen(false);
    }
  };

  const today = new Date();
  const isMonthView = viewMode === "mes";

  return (
    <div className="flex-1 flex flex-col overflow-hidden">
      <TopBar title="Calendário" subtitle="Plantões, consultas e procedimentos · Ala UTI 2" />

      <div className="flex items-center justify-between px-4 md:px-8 pt-5">
        <div className="flex items-center gap-3">
          <button onClick={handlePrev} className="w-9 h-9 border flex items-center justify-center" style={styles.navButton}>
            <ChevronLeft size={16} color={styles.navIconColor} />
          </button>
          <p className="display text-[1.05rem] font-semibold min-w-[190px]" style={styles.weekLabel}>
            {rangeLabel}
          </p>
          <button onClick={handleNext} className="w-9 h-9 border flex items-center justify-center" style={styles.navButton}>
            <ChevronRight size={16} color={styles.navIconColor} />
          </button>

          {/* Toggle Semana / Mês */}
          <div className="flex items-center gap-1 border p-0.5 ml-2" style={styles.toggleWrap}>
            {(["semana", "mes"] as ViewMode[]).map((mode) => (
              <button
                key={mode}
                onClick={() => setViewMode(mode)}
                className="h-7 px-3 rounded-md text-[12px] font-semibold capitalize"
                style={getToggleButtonStyle(viewMode === mode)}
              >
                {mode === "semana" ? "Semana" : "Mês"}
              </button>
            ))}
          </div>
        </div>

        <div className="flex items-center gap-4">
          {Object.entries(eventTypeMeta).map(([k, v]) => (
            <div key={k} className="flex items-center gap-1.5">
              <span className="w-2.5 h-2.5 rounded-full" style={getLegendDotStyle(v.color)} />
              <span className="text-[11.5px]" style={styles.legendLabel}>
                {v.label}
              </span>
            </div>
          ))}

          <button
            onClick={() => setModalOpen(true)}
            className="h-9 px-3.5 flex items-center gap-1.5 text-[12.5px] font-semibold text-white"
            style={{ background: COLORS.orange }}
          >
            <Plus size={14} />
            Novo Evento
          </button>
        </div>
      </div>

      <div
        className={`flex-1 mx-4 md:mx-8 my-4 md:my-5 bg-white border overflow-hidden ${
          isMonthView ? "flex overflow-x-auto" : "grid grid-cols-7"
        }`}
        style={styles.gridBorder}
      >
        {days.map((day, i) => {
          const iso = toISODate(day);
          return (
            <div
              key={iso}
              className={`flex flex-col border-r last:border-0 overflow-y-auto ${isMonthView ? "flex-none w-[140px] md:w-[160px]" : ""}`}
              style={styles.gridBorder}
            >
              <div className="h-11 flex items-center justify-center border-b shrink-0" style={styles.dayHeader}>
                <span className="text-[12px] font-semibold" style={getDayLabelStyle(isSameDay(day, today))}>
                  {formatDayLabel(day)}
                </span>
              </div>
              <div className="flex-1 p-2 flex flex-col gap-2">
                {events
                  .filter((e) => e.data === iso)
                  .map((e, j) => {
                    const meta = eventTypeMeta[e.tipo as TipoEventoKey]!;
                    return (
                      <div
                        key={j}
                        className="p-2 border-l-[3px]"
                        style={getEventCardStyle(meta.color)}
                        onMouseDown={(mouseEvent) => handleMouseDown(mouseEvent, e)}
                        onMouseMove={handleMouseMove}
                        onMouseUp={handleMouseUp}
                        onDoubleClick={() => handleDoubleClick(e as EventoCalendario)}
                      >
                        <p className="mono text-[10.5px] font-semibold" style={styles.eventTime(meta.color)}>
                          {e.hora}
                        </p>
                        <p className="text-[11px] font-medium leading-snug mt-0.5" style={styles.eventTitle}>
                          {e.titulo}
                        </p>
                      </div>
                    );
                  })}
              </div>
            </div>
          );
        })}
      </div>

      <NovoEventoModal open={modalOpen} onClose={() => setModalOpen(false)} onSave={handleSaveEvento} />
    </div>
  );
};